int exp(int b, int e) {
	if (e == 0) {
		return 1;
	}

	int x = exp(b, e / 2);

	if (e % 2 == 0) {
		return x * x;
	}
	if (e % 2 == 1) {
		return x * x * b;
	}
}
```


